// Merge the request with the evaluation's ruling.
const solicitud = $('Con los datos minimos').first().json;
const salida = [];
for (const item of $input.all()) {
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let ev;
  try {
    ev = JSON.parse(bruto);
  } catch (error) {
    ev = { dictamen: 'informacion_insuficiente', condiciones: [], alternativa: null, nivel_datos: 'no evaluado', preguntas: ['la evaluacion no fue parseable: revisar a mano'], razonamiento: bruto.slice(0, 200) };
  }
  salida.push({
    json: {
      ...solicitud,
      evaluacion: ev.dictamen ?? 'informacion_insuficiente',
      condiciones: (ev.condiciones ?? []).join(' | '),
      alternativa: ev.alternativa ?? '',
      nivel_datos: ev.nivel_datos ?? '',
      preguntas: (ev.preguntas ?? []).join(' | '),
      razonamiento: ev.razonamiento ?? '',
    },
  });
}
return salida;

